/* Interactive view of the posterior generated by analysis/ai_control_growth/model.py. */
(() => {
    'use strict';
    const D = window.AI_CONTROL_GROWTH;
    if (!D) return;
    const NS = 'http://www.w3.org/2000/svg';
    const yearMs = 365.25 * 86400000;
    const origin = Date.parse(D.origin), reference = Date.parse(D.referenceDate);
    const view = {measure:'attacker', attackerHours:24, attackgrowth:0, level: .95, trust: 0, hours: 1, scale: 'log', leaderDate:D.evidenceEnd};
    let updateTestedModels = () => {};
    const protocolLabels = {
        'AI Control (Greenblatt et al.)':'Trusted editing (AI Control)',
        'greenblatt-monitor':'Trusted monitoring (AI Control)',
        'Ctrl-Z (Bhatt et al.)':'Ctrl-Z resampling', 'ctrlz-monitor':'Trusted monitoring (Ctrl-Z)',
        'Adaptive attacks on monitors (Terekhov et al.)':'Trusted monitoring (adaptive attacks)',
        'Control in SHADE-Arena (Kutasov et al.)':'SHADE resampling',
        'shade-monitor':'SHADE trusted monitoring', 'shade-critical-defer':'SHADE critical-action deferral',
        'linux-nano':'LinuxArena trusted monitoring',
        'Retrying vs resampling (Lucassen & Kaufman)':'Resampling for information',
        'retry-monitor':'BashArena trusted monitoring',
        'Attack selection (Ge-Wang et al.)':'Trusted monitoring (attack selection)',
        'Claude Code Auto Mode (Remedios et al.)':'Claude Code Auto Mode',
        'OpenAI Codex Guardian (Remedios et al.)':'Codex Guardian',
        'Hardened Auto Mode (Remedios et al.)':'Hardened Auto Mode++',
        'OpenAI Codex auto-review (OpenAI\'s own evaluation)':'Codex auto-review (self-report)',
        'Auto-mode-rogue':'Auto Mode (rogue-deployment case)',
        'untrusted-summarization':'Untrusted monitoring + summarization',
        'static-full-trajectory':'Full-trajectory trusted monitoring',
        'evasion-native-hooks':'Native-hook trusted monitoring',
        'bootstrap-trusted-only':'Bootstrap trusted-only baseline',
        'bootstrap-direct-monitor':'Direct monitoring (bootstrap study)',
        'bootstrapped-monitoring':'Bootstrapped monitoring'
    };
    const labelFor = p => protocolLabels[p.id] || p.label || p.id.replace('bootstrap-', 'Bootstrapped monitoring, ');
    const bestCache = new Map();
    const palette = ['#4a3aa7','#a45625','#187c63','#965186','#63732c','#ad4660','#437388','#735747'];
    function bestAt(date, before = false) {
        const key = date + (before ? '<' : '=');
        if (bestCache.has(key)) return bestCache.get(key);
        const eligible = D.protocols.map((p, j) => ({p, j})).filter(({p}) => before ? p.date < date : p.date <= date);
        if (!eligible.length) return null;
        const counts = new Array(D.protocols.length).fill(0);
        const scores = D.posterior.map((draw, i) => {
            let best = -Infinity, winner = -1;
            for (const {p, j} of eligible) {
                const score = draw[1] * p.year - D.gaps[i][j];
                if (score > best) {best = score; winner = j;}
            }
            counts[winner]++;
            return best;
        });
        const leaders = eligible.map(({p, j}) => ({protocol:p, probability:counts[j]/D.posterior.length}))
            .sort((a,b) => b.probability-a.probability);
        const value = {scores, leaders};
        bestCache.set(key, value);
        return value;
    }
    const scenarioKey = f => Number(f).toFixed(1);
    const percent = p => p < .01 ? '<1%' : p > .99 ? '>99%' : `${Math.round(100 * p)}%`;
    const logit = p => Math.log(p / (1 - p));
    const dateLabel = d => new Date(d).toLocaleDateString('en-GB', {day:'numeric', month:'short', year:'numeric', timeZone:'UTC'});
    function duration(minutes) {
        if (minutes < 1 / 60) return `${(minutes * 60).toPrecision(2)} seconds`;
        if (minutes < 1) return `${(minutes * 60).toFixed(1)} seconds`;
        if (minutes < 60) return `${minutes.toPrecision(2)} min`;
        if (minutes < 60000) return `${Number((minutes / 60).toPrecision(2)).toLocaleString('en')} hours`;
        return `${(minutes / 60).toExponential(1)} hours`;
    }
    function fromLogDuration(logMinutes) {
        if (logMinutes < 0) return 'below the one-minute display limit';
        if (logMinutes > 690) return 'beyond the meaningful extrapolation range';
        return duration(Math.exp(logMinutes));
    }
    function quantile(sorted, p) {
        const i = p * (sorted.length - 1), lo = Math.floor(i), f = i - lo;
        return sorted[lo] * (1 - f) + sorted[Math.min(lo + 1, sorted.length - 1)] * f;
    }
    function intervalAt(date, before = false) {
        const sinceRef = (Date.parse(date) - reference) / yearMs;
        const monitor = Math.log(view.hours * 60 / 4);
        const threshold = logit(view.level);
        const best = bestAt(date, before);
        const sorted = D.posterior.map(([alpha, progress, bm, ba, gf], i) => {
            if (view.measure === 'monitor') {
                const attacker = Math.log(view.attackerHours * 60 / 4) + view.attackgrowth * gf * sinceRef;
                return Math.log(4) + (threshold - alpha - best.scores[i] + ba * attacker) / bm;
            }
            return Math.log(4) + (alpha + best.scores[i] + bm * (monitor + view.trust * gf * sinceRef) - threshold) / ba;
        }).sort((a, b) => a - b);
        return {date, lo:quantile(sorted, .05), mid:quantile(sorted, .5), hi:quantile(sorted, .95), leaders:best.leaders};
    }
    function svgEl(tag, attributes, parent, text) {
        const e = document.createElementNS(NS, tag);
        for (const [key, value] of Object.entries(attributes || {})) e.setAttribute(key, value);
        if (text !== undefined) e.textContent = text;
        parent.appendChild(e);
        return e;
    }
    function textCell(row, value) {
        const td = document.createElement('td');
        td.textContent = value;
        row.appendChild(td);
        return td;
    }
    function linkCell(row, label, url) {
        const td = textCell(row, ''), a = document.createElement('a');
        a.href = url; a.textContent = label; td.appendChild(a);
    }
    function describe() {
        const inverse = view.measure === 'monitor';
        document.getElementById('ctl-attacker-setting').hidden = !inverse;
        for (const id of ['ctl-trust-setting','ctl-monitor-setting','ctl-growth-headline','ctl-model-summary']) document.getElementById(id).hidden = inverse;
        const key = scenarioKey(view.trust), probability = D.scenarios[key].p_control_faster;
        const all = D.assumptions.map(a => a.scenarios[key].p_control_faster);
        const latest = intervalAt(D.evidenceEnd);
        document.getElementById('ctl-probability').textContent = percent(probability);
        document.getElementById('ctl-sensitivity-range').textContent =
            `Across the ${all.length} tested assumption sets: ${percent(Math.min(...all))} to ${percent(Math.max(...all))}.`;
        document.getElementById('ctl-current-capability').textContent = fromLogDuration(latest.mid);
        document.getElementById('ctl-current-caption').textContent =
            inverse ? `weakest sufficient trusted-monitor horizon at ${Math.round(view.level * 100)}% control safety, on ${dateLabel(D.evidenceEnd)} (lower is better)` : `implied attacker horizon at ${Math.round(view.level * 100)}% control safety, on ${dateLabel(D.evidenceEnd)}`;
        document.getElementById('ctl-current-interval').textContent =
            `90% fitted interval: ${fromLogDuration(latest.lo)} to ${fromLogDuration(latest.hi)}.`;
        const trend = view.trust === 0 ? 'The trusted model stays fixed throughout the graph.' :
            `The trusted model improves at ${view.trust === 1 ? 'the frontier’s' : 'half the frontier’s'} proportional growth rate, anchored to the entered capability in September 2026.`;
        document.getElementById('ctl-scenario-note').textContent =
            `Hypothetical trusted model: ${duration(view.hours * 60)} at the reference date. ${trend} Earlier values are counterfactual if that trusted model was not available then.`;
        document.getElementById('ctl-model-summary').textContent =
            `In the reference fit, control ${probability < .5 ? 'probably loses' : 'probably gains'} ground in this trusted-model scenario. ` +
            `The estimate changes substantially with assumptions about how evaluations transfer and how much progress they leave unobserved. ` +
            `It estimates a historical trend across the published evidence; extending that trend is a further assumption.`;
        if (inverse) document.getElementById('ctl-scenario-note').textContent = `Required trusted monitor against a hypothetical ${duration(view.attackerHours * 60)} attacker at the reference date, ${view.attackgrowth ? 'growing at the frontier rate' : 'held fixed over time'}. Lower is better. The same posterior is inverted; no refit or claim that this monitor exists is implied.`;
        showLeader(view.leaderDate, bestAt(view.leaderDate).leaders);
        const drift = D.attackDrift['0.5'][key].p_control_faster;
        document.getElementById('ctl-attack-drift').textContent = percent(drift);
        for (const cell of document.querySelectorAll('#ctl-assumptions [data-trust]')) {
            cell.classList.toggle('selected', Number(cell.dataset.trust) === view.trust);
        }
    }
    function showLeader(date, leaders) {
        const first = leaders[0];
        document.getElementById('ctl-leader-readout').textContent =
            `${dateLabel(date)} — most likely best: ${labelFor(first.protocol)} (${percent(first.probability)} probability of being best among available candidates).`;
        const describeModels = names => names.map(name => {
            const c = D.testedCapabilities[name];
            return c && !c.unplaced ? `${name}: ${duration(c.p50)}${c.estimated ? ' (estimated)' : ' (METR)'}` : `${name}: capability not placed`;
        }).join('; ');
        const p = first.protocol;
        document.getElementById('ctl-tested-readout').textContent =
            `As tested — attacker${p.testedAttackers.length > 1 ? 's' : ''}: ${describeModels(p.testedAttackers)}. ` +
            `Trusted monitor${p.testedMonitors.length > 1 ? 's' : ''}: ${describeModels(p.testedMonitors)}.`;
    }
    function selectLeader(date) {
        view.leaderDate = date;
        const period = leaderPeriods().find(p => p.date <= date && date < p.end) || leaderPeriods().at(-1);
        document.getElementById('ctl-leader-select').value = period.date;
        showLeader(date, bestAt(date).leaders);
        updateTestedModels();
    }
    function leaderPeriods() {
        const periods = [];
        for (const date of [...new Set(D.protocols.map(p => p.date))].sort()) {
            const leader = bestAt(date).leaders[0];
            if (periods.at(-1)?.protocol.id === leader.protocol.id) continue;
            if (periods.length) periods.at(-1).end = date;
            periods.push({date, end:D.chartEnd, protocol:leader.protocol});
        }
        return periods;
    }
    function testedModels(protocol) {
        return [
            ...protocol.testedAttackers.map(name => ({name, role:'attacker', color:'#bb5816'})),
            ...protocol.testedMonitors.map(name => ({name, role:'monitor', color:'#167954'}))
        ].map(m => ({...m, capability:D.testedCapabilities[m.name]}));
    }
    function draw() {
        const container = document.getElementById('ctl-chart');
        container.replaceChildren();
        const width = 1200, height = 620;
        const m = {left:100, right:35, top:25, bottom:90};
        const iw = width - m.left - m.right, ih = height - m.top - m.bottom;
        const start = Date.parse('2023-01-01'), end = Date.parse(D.chartEnd);
        const dates = [D.origin];
        for (let y = 2024; y <= 2026; y++) for (let month = 1; month <= 12; month++) {
            const date = `${y}-${String(month).padStart(2, '0')}-01`;
            if (date <= D.evidenceEnd) dates.push(date);
        }
        dates.push(D.evidenceEnd);
        const publications = [...new Set(D.protocols.map(p => p.date))];
        dates.push(...publications);
        const points = [];
        for (const date of [...new Set(dates)].sort()) {
            if (date > D.origin && publications.includes(date)) points.push(intervalAt(date, true));
            points.push(intervalAt(date));
        }
        const projection = intervalAt(D.chartEnd);
        const allPoints = [...points, projection];
        const periods = leaderPeriods();
        const tested = periods.flatMap(p => testedModels(p.protocol)).filter(m => m.capability);
        const upper = Math.max(...allPoints.map(p => p.hi), ...D.frontier.map(p => Math.log(p.hi)), ...tested.map(m => Math.log(m.capability.hi)));
        const lower = Math.min(...allPoints.map(p => p.lo), ...D.frontier.map(p => Math.log(p.lo)), ...tested.map(m => Math.log(m.capability.lo)));
        let minLog = 0, maxLog = Math.max(1, upper + .3);
        let linearMax = Math.exp(upper) * 1.12;
        const x = date => m.left + (Date.parse(date) - start) / (end - start) * iw;
        const yLog = logMinutes => view.scale === 'log'
            ? m.top + ih * (maxLog - Math.max(0, logMinutes)) / (maxLog - minLog)
            : m.top + ih * (1 - Math.exp(Math.max(0, logMinutes)) / linearMax);
        const svg = svgEl('svg', {viewBox:`0 0 ${width} ${height}`, role:'img',
            'aria-labelledby':'ctl-chart-title ctl-chart-desc'}, container);
        svgEl('title', {id:'ctl-chart-title'}, svg, 'Frontier capability and uncertain estimated control capability over time');
        svgEl('desc', {id:'ctl-chart-desc'}, svg,
            `Blue points are model time horizons. Orange triangles and green squares show historical leaders’ tested attackers and trusted monitors. Hover or focus markers for model names and capabilities. Select another period using the timeline or leader selector. The purple curve shows ${view.measure === 'monitor' ? 'the weakest sufficient trusted monitor' : 'the strongest controllable attacker'} at ${view.level * 100}% safety, with a pointwise 90% credible interval.`);
        const ticks = [];
        if (view.scale === 'log') {
            const candidates = [1/600, 1/60, 1/6, 1, 10, 60, 600, 6000, 60000, 600000, 6000000, 60000000];
            for (const v of candidates) if (Math.log(v) >= minLog && Math.log(v) <= maxLog) ticks.push(v);
            if (ticks.length < 3 || Math.log(candidates[0]) > minLog || Math.log(candidates.at(-1)) < maxLog) {
                ticks.length = 0;
                const step = Math.max(1, Math.ceil((maxLog - minLog) / Math.LN10 / 8));
                for (let n = Math.ceil(minLog / Math.LN10); n * Math.LN10 <= maxLog; n += step) ticks.push(10 ** n);
            }
        } else {
            const rough = linearMax / 6, power = 10 ** Math.floor(Math.log10(rough));
            const step = [1, 2, 5, 10].map(v => v * power).find(v => v >= rough);
            linearMax = Math.ceil(linearMax / step) * step;
            for (let v = 0; v <= linearMax * 1.001; v += step) ticks.push(v);
        }
        for (const value of ticks) {
            const yy = value === 0 ? m.top + ih : yLog(Math.log(value));
            svgEl('line', {x1:m.left, x2:width-m.right, y1:yy, y2:yy, stroke:'#e6e5e0'}, svg);
            svgEl('text', {x:m.left-10, y:yy+4, 'text-anchor':'end', fill:'#52514e', 'font-size':12}, svg, value === 0 ? '0' : duration(value));
        }
        for (let year = 2023; year <= 2026; year++) for (const month of ['01', '07']) {
            const date = `${year}-${month}-01`, xx = x(date);
            svgEl('line', {x1:xx, x2:xx, y1:m.top, y2:m.top+ih, stroke:'#e6e5e0'}, svg);
            svgEl('text', {x:xx+3, y:m.top+ih+23, fill:'#52514e', 'font-size':12}, svg, month === '01' ? String(year) : 'Jul');
        }
        svgEl('text', {x:20, y:m.top+ih/2, transform:`rotate(-90 20 ${m.top+ih/2})`, 'text-anchor':'middle', fill:'#52514e', 'font-size':13}, svg,
            `${view.measure === 'monitor' ? 'Required monitor (lower is better)' : 'Capability'}: 50% task-completion horizon${view.scale === 'log' ? ' (log scale)' : ''}`);
        const path = pts => pts.map(([xx, yy], i) => `${i ? 'L' : 'M'}${xx.toFixed(2)},${yy.toFixed(2)}`).join(' ');
        const band = [...points.map(p => [x(p.date), yLog(p.hi)]), ...points.toReversed().map(p => [x(p.date), yLog(p.lo)])];
        svgEl('path', {d:path(band)+' Z', fill:'#4a3aa7', opacity:.15}, svg);
        const last = points.at(-1);
        const forecastBand = [[x(last.date), yLog(last.lo)], [x(last.date), yLog(last.hi)], [x(projection.date), yLog(projection.hi)], [x(projection.date), yLog(projection.lo)]];
        svgEl('path', {d:path(forecastBand)+' Z', fill:'#4a3aa7', opacity:.07}, svg);
        svgEl('path', {d:path(points.map(p => [x(p.date), yLog(p.mid)])), fill:'none', stroke:'#4a3aa7', 'stroke-width':3}, svg);
        svgEl('path', {d:path([[x(last.date), yLog(last.mid)], [x(projection.date), yLog(projection.mid)]]), fill:'none', stroke:'#4a3aa7', 'stroke-width':3, opacity:.45}, svg);
        for (const date of [D.origin, '2025-01-01', '2026-01-01', D.evidenceEnd]) {
            const p = intervalAt(date), xx = x(date), lo = yLog(p.lo), hi = yLog(p.hi);
            const label = `${dateLabel(date)}: ${view.measure === 'monitor' ? 'required trusted monitor' : 'controllable attacker'} ${fromLogDuration(p.mid)}; 90% interval ${fromLogDuration(p.lo)} to ${fromLogDuration(p.hi)}, at ${view.level*100}% safety.`;
            const g = svgEl('g', {tabindex:0, role:'img', 'aria-label':label}, svg);
            svgEl('title', {}, g, label + ` Most likely best: ${labelFor(p.leaders[0].protocol)} (${percent(p.leaders[0].probability)}).`);
            g.addEventListener('mouseenter', () => selectLeader(date));
            g.addEventListener('focus', () => selectLeader(date));
            svgEl('line', {x1:xx, x2:xx, y1:lo, y2:hi, stroke:'#4a3aa7', 'stroke-width':1.5, opacity:.65}, g);
            for (const yy of (p.lo < 0 ? [hi] : [lo, hi])) svgEl('line', {x1:xx-5, x2:xx+5, y1:yy, y2:yy, stroke:'#4a3aa7', 'stroke-width':1.5}, g);
            if (p.lo < 0) {
                const bottom = yLog(0);
                const arrow = svgEl('path', {'data-below-range':'', d:`M${xx},${bottom-12} V${bottom} M${xx-5},${bottom-5} L${xx},${bottom} L${xx+5},${bottom-5}`, fill:'none', stroke:'#4a3aa7', 'stroke-width':2}, g);
                svgEl('title', {}, arrow, 'Interval extends below the one-minute display limit; posterior uncertainty is retained.');
            }
            svgEl('circle', {cx:xx, cy:yLog(p.mid), r:3.5, fill:'#4a3aa7'}, g);
            svgEl('rect', {x:xx-8, y:hi, width:16, height:Math.max(8,lo-hi), fill:'transparent'}, g);
        }
        for (const model of D.frontier) {
            const xx = x(model.date), yy = yLog(Math.log(model.p50));
            const label = `${model.name}, ${model.date}: ${duration(model.p50)}; ${model.estimated ? 'estimated ECI range' : 'METR 95% CI'} ${duration(model.lo)} to ${duration(model.hi)}.`;
            const g = svgEl('g', {tabindex:0, role:'img', 'aria-label':label, class:'ctl-frontier-point'}, svg);
            svgEl('title', {}, g, label);
            svgEl('line', {x1:xx, x2:xx, y1:yLog(Math.log(model.lo)), y2:yLog(Math.log(model.hi)), stroke:'#2a78d6', class:'ctl-frontier-range'}, g);
            svgEl('circle', {cx:xx, cy:yy, r:5, fill:model.estimated ? '#fcfcfb' : '#2a78d6', stroke:model.estimated ? '#2a78d6' : '#fcfcfb', 'stroke-width':2}, g);
        }
        // Retain historical markers, with model details available on hover.
        const testedLayer = svgEl('g', {'data-tested-layer':''}, svg);
        updateTestedModels = () => {
            testedLayer.replaceChildren();
            const selectedPeriod = periods.find(p => p.date <= view.leaderDate && view.leaderDate < p.end) || periods.at(-1);
            for (const period of [...periods.filter(p => p !== selectedPeriod), selectedPeriod]) {
                const selected = period === selectedPeriod;
                for (const model of testedModels(period.protocol)) {
                    const c = model.capability;
                    if (!c || c.unplaced) continue; // Named explicitly as unplaced in the readout.
                    const offset = model.role === 'attacker' ? 4 : 10;
                    const xx = x(period.date) + Math.min(offset, Math.max(1, x(period.end)-x(period.date)-2));
                    const yy = yLog(Math.log(c.p50));
                    const role = model.role === 'attacker' ? 'Tested attacker' : 'Tested trusted monitor';
                    const label = `${labelFor(period.protocol)} — ${role}: ${model.name}, ${duration(c.p50)}${c.estimated ? ' (estimated)' : ' (METR)'}. ${c.rangeLabel}: ${duration(c.lo)} to ${duration(c.hi)}. Evaluation ${period.protocol.date}; leader period ${period.date} to ${period.end}.`;
                    const g = svgEl('g', {tabindex:0, role:'img', 'aria-label':label,
                        'data-tested-role':model.role, 'data-model':model.name, 'data-protocol':period.protocol.id,
                        'data-selected':String(selected), class:`ctl-tested-point${selected ? ' ctl-tested-selected' : ''}`,
                        opacity:selected ? 1 : .65, style:'cursor:pointer'}, testedLayer);
                    svgEl('title', {}, g, label);
                    g.addEventListener('click', () => selectLeader(period.date));
                    g.addEventListener('keydown', event => {
                        if (event.key === 'Enter' || event.key === ' ') {event.preventDefault(); selectLeader(period.date);}
                    });
                    const lo = yLog(Math.log(c.lo)), hi = yLog(Math.log(c.hi));
                    svgEl('line', {x1:xx, x2:xx, y1:lo, y2:hi, stroke:model.color, class:'ctl-tested-range'}, g);
                    const fill = c.estimated ? '#fcfcfb' : model.color;
                    if (model.role === 'attacker') svgEl('path', {d:`M${xx},${yy-6} L${xx+6},${yy+5} L${xx-6},${yy+5} Z`, fill, stroke:model.color, 'stroke-width':2}, g);
                    else svgEl('rect', {x:xx-5, y:yy-5, width:10, height:10, fill, stroke:model.color, 'stroke-width':2}, g);
                }
            }
        };
        updateTestedModels();
        svgEl('line', {x1:m.left, x2:width-m.right, y1:m.top+ih, y2:m.top+ih, stroke:'#999'}, svg);
        const studies = new Map();
        for (const o of D.observations) if (!studies.has(o.study)) studies.set(o.study, o.date);
        for (const [id, date] of studies) {
            const g = svgEl('g', {tabindex:0}, svg);
            svgEl('title', {}, g, `${date}: ${D.sources.find(s => s.id === id).title}`);
            svgEl('line', {x1:x(date), x2:x(date), y1:m.top+ih+33, y2:m.top+ih+42, stroke:'#777', 'stroke-width':2}, g);
        }
        svgEl('text', {x:m.left, y:height-14, fill:'#777', 'font-size':11}, svg, 'Evaluation publication dates');
        // A colored timeline identifies the modal protocol without implying
        // that one deterministic winner generated every posterior curve.
        for (let i=0; i<publications.length; i++) {
            const date = publications[i], next = publications[i+1] || D.chartEnd;
            const best = bestAt(date), leader = best.leaders[0];
            const j = D.protocols.findIndex(p => p.id === leader.protocol.id);
            const rect = svgEl('rect', {x:x(date), y:m.top+ih+54, width:Math.max(1,x(next)-x(date)), height:8,
                fill:palette[j%palette.length], tabindex:0, role:'button', style:'cursor:pointer', 'data-leader-date':date,
                'aria-label':`${date} to ${next}: ${labelFor(leader.protocol)}, ${percent(leader.probability)} probability of being best`}, svg);
            svgEl('title', {}, rect, `${date} to ${next}: ${labelFor(leader.protocol)} (${percent(leader.probability)}). Hover an error bar or see the protocol table for alternatives.`);
            rect.addEventListener('mouseenter', () => selectLeader(date));
            rect.addEventListener('focus', () => selectLeader(date));
            rect.addEventListener('click', () => selectLeader(date));
            rect.addEventListener('keydown', event => {
                if (event.key === 'Enter' || event.key === ' ') {event.preventDefault(); selectLeader(date);}
            });
        }
    }
    function tables() {
        const selector = document.getElementById('ctl-leader-select');
        for (const period of leaderPeriods()) {
            const option = document.createElement('option');
            option.value = period.date;
            option.textContent = `${dateLabel(period.date)} — ${labelFor(period.protocol)}`;
            selector.appendChild(option);
        }
        selector.value = leaderPeriods().at(-1).date;
        selector.addEventListener('change', () => selectLeader(selector.value));
        const leaderBody = document.querySelector('#ctl-leaders tbody');
        let previousLeader = null;
        for (const date of [...new Set(D.protocols.map(p => p.date))].sort()) {
            const leaders = bestAt(date).leaders, first = leaders[0], row = document.createElement('tr');
            textCell(row, dateLabel(date));
            const source = D.sources.find(s => s.id === first.protocol.study);
            linkCell(row, labelFor(first.protocol), source.url);
            textCell(row, percent(first.probability));
            textCell(row, leaders.slice(1,3).map(l => `${labelFor(l.protocol)} (${percent(l.probability)})`).join('; '));
            leaderBody.appendChild(row);
            if (first.protocol.id !== previousLeader) {
                const item = document.createElement('span'), swatch = document.createElement('i');
                const j = D.protocols.findIndex(p => p.id === first.protocol.id);
                swatch.style.cssText = `display:inline-block;width:18px;height:7px;background:${palette[j%palette.length]}`;
                item.append(swatch, document.createTextNode(`${dateLabel(date)}: ${labelFor(first.protocol)}`));
                document.getElementById('ctl-leader-legend').appendChild(item);
                previousLeader = first.protocol.id;
            }
        }
        const assumptions = document.querySelector('#ctl-assumptions tbody');
        for (const a of D.assumptions) {
            const row = document.createElement('tr');
            textCell(row, a.name);
            for (const f of [0, .5, 1]) {
                const td = textCell(row, percent(a.scenarios[scenarioKey(f)].p_control_faster));
                td.dataset.trust = f;
            }
            assumptions.appendChild(row);
        }
        const sourceBody = document.querySelector('#ctl-sources tbody');
        for (const source of D.sources) {
            const row = document.createElement('tr');
            linkCell(row, source.title, source.url);
            textCell(row, source.count || (source.id === 'metr' ? 'Capability trend' : 'Model structure'));
            textCell(row, source.role);
            sourceBody.appendChild(row);
        }
        const obsBody = document.querySelector('#ctl-observations tbody');
        for (const o of D.observations) {
            const row = document.createElement('tr'), source = D.sources.find(s => s.id === o.study);
            linkCell(row, source.title, source.url);
            textCell(row, o.attacker); textCell(row, o.monitor); textCell(row, o.metric.replaceAll('_', ' '));
            const p = v => `${(100*v).toFixed(1)}%`;
            textCell(row, o.value !== undefined ? p(o.value) : o.lower !== undefined && o.upper !== undefined ? `${p(o.lower)}–${p(o.upper)}` : o.upper !== undefined ? `≤ ${p(o.upper)}` : `≥ ${p(o.lower)}`);
            textCell(row, o.detail || 'Reported within-study result, transported with uncertainty.');
            obsBody.appendChild(row);
        }
        document.getElementById('ctl-evidence-summary').textContent =
            `${D.observations.length} observations and bounds; ${D.variants.length} indexed variants, including ${D.variants.filter(v => v.status === "quantitative").length} with numerical evidence. Figure-only and qualitative variants remain listed below. METR supplies the capability trend.`;
        const inventory = document.getElementById('ctl-variants');
        for (const v of D.variants) {
            const row = document.createElement('tr');
            const source = D.sources.find(s => s.id === v.study);
            linkCell(row, v.label, source.url);
            textCell(row, source.title + ' — ' + v.locations.join('; '));
            textCell(row, v.status === 'quantitative' ? `${v.observation_ids.length} observations${!v.candidate_eligible ? '; baseline only' : v.leader_eligible === false ? '; attack context only' : ''}` : v.status);
            textCell(row, [v.notes, v.cost].filter(Boolean).join(' '));
            inventory.appendChild(row);
        }
        document.getElementById('ctl-diagnostics').textContent = D.diagnosticsPass
            ? 'Numerical checks passed: independent posterior-sampler checks, four chains per assumption set, split R-hat below 1.05 and effective sample sizes above 400 for the growth coefficients. The graph uses 2,000 retained posterior draws.'
            : 'The numerical convergence checks need attention. Treat these results as provisional.';
    }
    document.addEventListener('DOMContentLoaded', () => {
        tables(); describe(); draw();
        for (const button of document.querySelectorAll('.ctl-controls button')) button.addEventListener('click', () => {
            const group = Object.keys(button.dataset)[0];
            view[group] = ['scale','measure'].includes(group) ? button.dataset[group] : Number(button.dataset[group]);
            for (const other of button.closest('fieldset').querySelectorAll('button')) other.setAttribute('aria-pressed', String(other === button));
            describe(); draw();
        });
        document.getElementById('ctl-attacker-hours').addEventListener('input', event => {
            if (!event.target.checkValidity() || !Number.isFinite(event.target.valueAsNumber)) return;
            view.attackerHours = event.target.valueAsNumber;
            describe(); draw();
        });
        document.getElementById('ctl-monitor-hours').addEventListener('input', event => {
            if (!event.target.checkValidity() || !Number.isFinite(event.target.valueAsNumber)) return;
            view.hours = event.target.valueAsNumber;
            describe(); draw();
        });
    });
})();
